def _looks_like_image_bytes(data):
    if not data or len(data) < 16:
        return False
    magic = (
        (b"\xff\xd8\xff",),  # JPEG
        (b"\x89PNG\r\n\x1a\n",),  # PNG
        (b"GIF87a",),
        (b"GIF89a",),
        (b"RIFF",),  # WEBP (RIFF....WEBP)
        (b"BM",),  # BMP
        (b"<svg", b"<?xml"),  # SVG
    )
    head = data[:16]
    return any(head.startswith(sig) for group in magic for sig in group)

