def ensure_favicon(soup, html_path, favicon_path, report, dry_run=False):
    head = soup.find("head")
    existing = None
    if head:
        for link in head.find_all("link"):
            rel = link.get("rel") or []
            rel = " ".join(rel) if isinstance(rel, list) else str(rel)
            if rel.lower() in FAVICON_RELS:
                existing = link
                break
    report.favicon_present = existing is not None

