# -*- coding: utf-8 -*-
"""
image_providers.py
===================

Real image-search backends for site_studio, using OFFICIAL free APIs instead of
scraping. Scraping Google Images / Pexels / etc. directly was tried and reliably
blocked (403 from anti-bot protection) even with full browser-like headers - only an
interactive fetch tool with different infrastructure got through, which a standalone
script running on its own does not have. Official APIs are the durable alternative:

  - Pexels:  free instant API key at https://www.pexels.com/api/  (200 req/hour)
  - Pixabay: free instant API key at https://pixabay.com/api/docs/ (very high limits)
  - Google Custom Search: needs a Google Cloud API key + a Programmable Search Engine
    ID (cx) configured for "image search" - https://programmablesearchengine.google.com/
    Free tier: 100 queries/day. This is literal Google Images results, at the cost of
    a slightly more involved one-time setup.

Each search_* function returns a list of raw image bytes (already downloaded).
"""

import json
import urllib.error
import urllib.parse
import urllib.request


class ProviderError(Exception):
    pass


def _download(url, ua="site-studio/1.0 (local tool)"):
    req = urllib.request.Request(url, headers={"User-Agent": ua})
    with urllib.request.urlopen(req, timeout=30) as resp:
        return resp.read()


def search_pexels(cfg, query, count):
    api_key = cfg.get("api_key")
    params = urllib.parse.urlencode({"query": query, "per_page": max(1, min(count, 80))})
    url = f"https://api.pexels.com/v1/search?{params}"
    req = urllib.request.Request(url, headers={"Authorization": api_key})
    try:
        with urllib.request.urlopen(req, timeout=20) as resp:
            data = json.loads(resp.read())
    except urllib.error.HTTPError as e:
        raise ProviderError(f"Pexels API error {e.code}: {e.read().decode(errors='replace')[:300]}")
    photos = data.get("photos", [])
    if not photos:
        raise ProviderError(f"Pexels returned no results for '{query}'")
    out = []
    for p in photos[:count]:
        src = p.get("src", {})
        chosen = src.get("large2x") or src.get("large") or src.get("original")
        if chosen:
            try:
                out.append(_download(chosen))
            except Exception:
                continue
    if not out:
        raise ProviderError("Pexels matched results but none could be downloaded")
    return out


def search_pixabay(cfg, query, count):
    api_key = cfg.get("api_key")
    params = urllib.parse.urlencode(
        {"key": api_key, "q": query, "image_type": "photo", "per_page": max(3, min(count, 200))}
    )
    url = f"https://pixabay.com/api/?{params}"
    try:
        with urllib.request.urlopen(url, timeout=20) as resp:
            data = json.loads(resp.read())
    except urllib.error.HTTPError as e:
        raise ProviderError(f"Pixabay API error {e.code}: {e.read().decode(errors='replace')[:300]}")
    hits = data.get("hits", [])
    if not hits:
        raise ProviderError(f"Pixabay returned no results for '{query}'")
    out = []
    for h in hits[:count]:
        chosen = h.get("largeImageURL") or h.get("webformatURL")
        if chosen:
            try:
                out.append(_download(chosen))
            except Exception:
                continue
    if not out:
        raise ProviderError("Pixabay matched results but none could be downloaded")
    return out


def search_google_cse(cfg, query, count):
    api_key = cfg.get("api_key")
    cx = cfg.get("cx")
    out = []
    start = 1
    while len(out) < count and start <= 91:
        params = urllib.parse.urlencode(
            {
                "key": api_key,
                "cx": cx,
                "q": query,
                "searchType": "image",
                "num": max(1, min(10, count - len(out))),
                "start": start,
            }
        )
        url = f"https://www.googleapis.com/customsearch/v1?{params}"
        try:
            with urllib.request.urlopen(url, timeout=20) as resp:
                data = json.loads(resp.read())
        except urllib.error.HTTPError as e:
            raise ProviderError(f"Google Custom Search API error {e.code}: {e.read().decode(errors='replace')[:300]}")
        items = data.get("items", [])
        if not items:
            break
        for item in items:
            link = item.get("link")
            if not link:
                continue
            try:
                out.append(_download(link))
            except Exception:
                continue
            if len(out) >= count:
                break
        start += 10
    if not out:
        raise ProviderError(f"Google Custom Search returned no usable images for '{query}'")
    return out


PROVIDERS = {
    "pexels": {
        "label": "Pexels",
        "setup_hint": "Free instant API key: https://www.pexels.com/api/",
        "needs": ["api_key"],
        "fn": search_pexels,
    },
    "pixabay": {
        "label": "Pixabay",
        "setup_hint": "Free instant API key: https://pixabay.com/api/docs/",
        "needs": ["api_key"],
        "fn": search_pixabay,
    },
    "google": {
        "label": "Google Images (Custom Search)",
        "setup_hint": (
            "Needs a Google Cloud API key AND a Programmable Search Engine ID (cx) with "
            "image search enabled: https://programmablesearchengine.google.com/ - 100 free/day."
        ),
        "needs": ["api_key", "cx"],
        "fn": search_google_cse,
    },
}

