#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
site_studio - a tiny local control panel for editing a cleaned PBN site export.

    python server.py <path-to-site-folder> [--port 5151]

Then open http://127.0.0.1:5151/ in a browser. From there you can:
  - point it at a site folder (containing index.html)
  - type a Google Fonts family (e.g. "Jost:wght@400;700") and apply it
  - type an image search query + a CSS selector for the gallery/card wrapper +
    how many images to fetch, pick a provider, and apply - it downloads real images
    and drops them into every <img> found inside elements matching that selector
  - see the actual site live in an embedded preview (served from /preview/), which
    reloads after every apply so you see the result immediately

Image search needs a free API key for at least one provider (Pexels/Pixabay are
instant sign-ups; Google Custom Search needs a bit more setup but is literal Google
Images results) - see image_providers.py for links. Plain scraping of Google/Pexels
search pages was tried and is reliably blocked by anti-bot protection, so this uses
official APIs instead - keys are entered once in the Settings panel and saved to
"<site>/.site_studio_config.json" (gitignore this file - it holds your API keys).
"""

import json
import sys
from pathlib import Path

from flask import Flask, jsonify, request, send_from_directory, render_template

sys.path.insert(0, str(Path(__file__).resolve().parent))
import image_providers  # noqa: E402
import site_edit  # noqa: E402

app = Flask(__name__)

STATE = {"site_dir": None, "html_path": None, "config_path": None}


def load_config():
    if not STATE["config_path"] or not STATE["config_path"].is_file():
        return {"providers": {}}
    try:
        return json.loads(STATE["config_path"].read_text(encoding="utf-8"))
    except Exception:
        return {"providers": {}}


def save_config(cfg):
    STATE["config_path"].write_text(json.dumps(cfg, indent=2, ensure_ascii=False), encoding="utf-8")


def set_site(site_dir_str):
    site_dir = Path(site_dir_str).resolve()
    html_path = site_dir / "index.html"
    if not html_path.is_file():
        raise ValueError(f"no index.html found in {site_dir}")
    STATE["site_dir"] = site_dir
    STATE["html_path"] = html_path
    STATE["config_path"] = site_dir / ".site_studio_config.json"


@app.route("/")
def index():
    return render_template("index.html")


@app.route("/api/status")
def api_status():
    cfg = load_config()
    configured = {}
    for key, provider in image_providers.PROVIDERS.items():
        pcfg = cfg.get("providers", {}).get(key, {})
        configured[key] = all(pcfg.get(need) for need in provider["needs"])
    return jsonify(
        {
            "site_dir": str(STATE["site_dir"]) if STATE["site_dir"] else None,
            "providers": {
                key: {
                    "label": p["label"],
                    "setup_hint": p["setup_hint"],
                    "needs": p["needs"],
                    "configured": configured[key],
                }
                for key, p in image_providers.PROVIDERS.items()
            },
        }
    )


@app.route("/api/set-site", methods=["POST"])
def api_set_site():
    try:
        set_site(request.json["site_dir"])
        return jsonify({"ok": True, "site_dir": str(STATE["site_dir"])})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 400


@app.route("/api/set-provider-key", methods=["POST"])
def api_set_provider_key():
    if not STATE["config_path"]:
        return jsonify({"ok": False, "error": "select a site folder first"}), 400
    body = request.json
    provider = body.get("provider")
    if provider not in image_providers.PROVIDERS:
        return jsonify({"ok": False, "error": f"unknown provider '{provider}'"}), 400
    cfg = load_config()
    cfg.setdefault("providers", {})[provider] = body.get("fields", {})
    save_config(cfg)
    return jsonify({"ok": True})


@app.route("/api/apply-font", methods=["POST"])
def api_apply_font():
    if not STATE["html_path"]:
        return jsonify({"ok": False, "error": "select a site folder first"}), 400
    family = (request.json or {}).get("family", "").strip()
    if not family:
        return jsonify({"ok": False, "error": "font family is required"}), 400
    try:
        result = site_edit.apply_font(STATE["html_path"], family)
        return jsonify({"ok": True, **result})
    except Exception as e:
        return jsonify({"ok": False, "error": str(e)}), 400


@app.route("/api/apply-images", methods=["POST"])
def api_apply_images():
    if not STATE["html_path"]:
        return jsonify({"ok": False, "error": "select a site folder first"}), 400
    body = request.json or {}
    provider_name = body.get("provider", "")
    query = body.get("query", "").strip()
    selector = body.get("selector", "").strip()
    try:
        count = max(1, min(80, int(body.get("count", 5))))
    except (TypeError, ValueError):
        return jsonify({"ok": False, "error": "count must be a number"}), 400

    if not query or not selector:
        return jsonify({"ok": False, "error": "query and selector are both required"}), 400
    provider = image_providers.PROVIDERS.get(provider_name)
    if not provider:
        return jsonify({"ok": False, "error": f"unknown provider '{provider_name}'"}), 400

    cfg = load_config()
    provider_cfg = cfg.get("providers", {}).get(provider_name, {})
    missing = [k for k in provider["needs"] if not provider_cfg.get(k)]
    if missing:
        return jsonify(
            {"ok": False, "error": f"provider '{provider_name}' needs {missing} - set it in Settings first"}
        ), 400

    try:
        images = provider["fn"](provider_cfg, query, count)
    except image_providers.ProviderError as e:
        return jsonify({"ok": False, "error": str(e)}), 400
    except Exception as e:
        return jsonify({"ok": False, "error": f"search failed: {e}"}), 400

    try:
        result = site_edit.apply_images(STATE["html_path"], selector, images)
        return jsonify({"ok": True, **result})
    except ValueError as e:
        return jsonify({"ok": False, "error": str(e)}), 400


@app.route("/preview/")
@app.route("/preview/<path:filename>")
def preview(filename="index.html"):
    if not STATE["site_dir"]:
        return "No site folder selected yet.", 400
    return send_from_directory(STATE["site_dir"], filename)


def main():
    import argparse

    parser = argparse.ArgumentParser(description="Local control panel + live preview for a cleaned site export.")
    parser.add_argument("site_dir", nargs="?", help="Path to the site folder (containing index.html)")
    parser.add_argument("--port", type=int, default=5151)
    args = parser.parse_args()

    if args.site_dir:
        set_site(args.site_dir)

    print(f"site_studio running at http://127.0.0.1:{args.port}/")
    if STATE["site_dir"]:
        print(f"editing: {STATE['site_dir']}")
    else:
        print("no site folder given - pick one in the web UI")

    app.run(host="127.0.0.1", port=args.port, debug=False)


if __name__ == "__main__":
    main()

