import json
import sys

src = sys.argv[1]
dst = sys.argv[2]

def fmt_content_block(block):
    t = block.get("type")
    if t == "text":
        return block.get("text", "")
    if t == "thinking":
        return "> _(thinking)_\n>\n> " + block.get("thinking", "").replace("\n", "\n> ")
    if t == "tool_use":
        name = block.get("name", "?")
        inp = block.get("input", {})
        try:
            inp_str = json.dumps(inp, ensure_ascii=False, indent=2)
        except Exception:
            inp_str = str(inp)
        if len(inp_str) > 4000:
            inp_str = inp_str[:4000] + "\n... [truncated input, too long]"
        return f"**Tool call: `{name}`**\n```json\n{inp_str}\n```"
    if t == "tool_result":
        content = block.get("content", "")
        if isinstance(content, list):
            parts = []
            for c in content:
                if isinstance(c, dict) and c.get("type") == "text":
                    parts.append(c.get("text", ""))
                else:
                    parts.append(str(c))
            content = "\n".join(parts)
        content = str(content)
        return f"**Tool result:**\n```\n{content}\n```"
    if t == "image":
        return "_[image content omitted]_"
    return f"_[unhandled block type: {t}]_\n```json\n{json.dumps(block, ensure_ascii=False)[:1000]}\n```"


def main():
    out = []
    with open(src, "r", encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                rec = json.loads(line)
            except json.JSONDecodeError:
                continue
            rtype = rec.get("type")
            if rtype not in ("user", "assistant"):
                continue
            msg = rec.get("message", {})
            role = msg.get("role", rtype)
            content = msg.get("content", "")
            ts = rec.get("timestamp", "")

            out.append(f"\n---\n\n### {role.upper()}  _{ts}_\n")

            if isinstance(content, str):
                out.append(content)
            elif isinstance(content, list):
                for block in content:
                    out.append(fmt_content_block(block))
                    out.append("")
            else:
                out.append(str(content))

    with open(dst, "w", encoding="utf-8") as f:
        f.write("\n".join(out))

    print(f"wrote {dst}")


if __name__ == "__main__":
    main()

